"""Regenerate ca_bundle.hpp from certs/*.pem (run when the bundled roots change)."""
from pathlib import Path

here = Path(__file__).resolve().parent
lines = ['#pragma once',
         '// Generated by gen_ca_bundle.py from certs/isrgrootx1.pem and certs/isrg-root-x2.pem',
         "// (Let's Encrypt ISRG Root X1 and X2). Do not edit by hand.",
         'namespace cssteroids::certs {',
         'inline constexpr char roots_pem[] =']
for name in ['isrgrootx1.pem', 'isrg-root-x2.pem']:
    for line in (here / 'certs' / name).read_text().strip().splitlines():
        lines.append('    "' + line.strip() + '\\n"')
lines[-1] += ';'
lines.append('}')
(here / 'ca_bundle.hpp').write_text('\n'.join(lines) + '\n', newline='\n')
